import{_ as e,c as a,o as r,ag as i}from"./chunks/framework.B-XtCDNB.js";const h=JSON.parse('{"title":"Attribute Input Type","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/attribute/attribute-input.md","filePath":"1.0/attribute/attribute-input.md","lastUpdated":1759498853000}'),d={name:"1.0/attribute/attribute-input.md"};function o(s,t,n,p,u,l){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="attribute-input-type" tabindex="-1">Attribute Input Type <a class="header-anchor" href="#attribute-input-type" aria-label="Permalink to &quot;Attribute Input Type&quot;">​</a></h1><p>Attributes can have different input types that determine not only how you enter the values for the attribute, but also how shoppers can select attributes in the case of options, or enter values.</p><p>Product Attributes are a set of characteristics that define a particular product or a group of goods. This means size, color, flavor, package type, etc. constitute attributes. Product attributes are not just about the general description of a product, but they speak about the value of products that makes it unique.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td>Text</td><td>A single-line input field for text.</td></tr><tr><td>Text Area</td><td>A multiple-line input field for entering paragraphs of text, such as a product description.</td></tr><tr><td>Boolean</td><td>Displays a switch to toggle between Yes and No.</td></tr><tr><td>Select</td><td>Displays a dropdown list of values that accepts a single selection of value</td></tr><tr><td>Multi Select</td><td>Displays a drop-down list of values that accepts multiple selections.</td></tr><tr><td>Date</td><td>Displays a date value in the preferred format.</td></tr><tr><td>Date Time</td><td>Displays a date and time value in the preferred format and time zone.</td></tr><tr><td>Image</td><td>This is used to show the image.</td></tr><tr><td>Gallery</td><td>A Gallery attribute that allows managing and displaying multiple images per product, enhancing the product media experience.</td></tr><tr><td>File</td><td>File attributes refers to a specific type of attributes that allows you to associate files with the product.</td></tr><tr><td>Checkbox</td><td>It represents a state or option that can be toggled.</td></tr><tr><td>Price</td><td>This input type is used to create price fields that are in addition to the predefined attributes: Prices.</td></tr></tbody></table>',4)])])}const f=e(d,[["render",o]]);export{h as __pageData,f as default};
